                        { value: 'false_positive', label: 'False positive' },
                        { value: 'unusual_behavior', label: 'Unusual transaction behavior' },
                        { value: 'normal_behavior', label: 'Normal customer behavior' },
                        { value: 'other', label: 'Other' }
