                    position: 'absolute',
                    top: `${Math.random() * 100}%`,
                    left: `${Math.random() * 100}%`,
                    width: '3px',
                    height: '3px',
                    background: `rgba(${[96, 167, 236][i % 3]}, ${[165, 139, 72][i % 3]}, ${[250, 250, 153][i % 3]}, 0.8)`,
                    borderRadius: '50%',
                    animation: `sparkle ${2 + Math.random() * 3}s ease-in-out infinite`,
                    animationDelay: `${Math.random() * 3}s`
